-- Generated by the Bridge's tests/gesture_bridge/test_control4_wire.py.
local T = require("testlib")
local codec = require("ha.codec")
local Catalog = require("ha.catalog")
local Selection = require("ha.selection")
local Indicators = require("ha.indicators")

local directory = arg[0]:match("^(.*[/])") or ""
local file = assert(io.open(directory .. "fixtures/control4-wire-v1.json"))
local wire = codec.decode(file:read("*a"))
file:close()

T.section("Real HA responses cross the catalogue, selection and indicator boundaries")
local calls = 0
local catalog = Catalog.new(function(message, callback)
  T.eq("the driver requests the companion catalog", message.service, "get_devices")
  calls = calls + 1
  T.eq(
    "a repeated refresh offers the received revision",
    message.service_data.revision,
    calls > 1 and wire.catalog.revision or nil
  )
  callback(true, codec.object({ response = calls == 1 and wire.catalog or wire.unchanged }))
end)
local first, fresh
catalog:refresh():next(function(meta)
  first = meta
end)
catalog:refresh():next(function(meta)
  fresh = meta
end)
T.truthy("the Bridge catalog publishes exactly one choice", first and first.total == 1)
T.eq("the Bridge freshness reply reuses that version", fresh, first)
local menu = catalog:read(first.revision)
local row = menu.entities[1]
local selected
Selection.resolve(
  catalog,
  function(message, callback)
    T.eq(
      "preparation targets the exact selected endpoint",
      { message.service, message.service_data.source_registry_id },
      { "prepare_device", wire.prepared.source_load.registry_id }
    )
    callback(true, codec.object({ response = wire.prepared }))
  end,
  codec.object({ choice_id = row.entity_id, family = "switch", revision = first.revision, prepare = true }),
  function()
    return true
  end
):next(function(config)
  selected = config
end)
T.truthy("the prepared configuration has ready input", selected and selected.input_ready)
T.eq("the selected switch retains its exact load", selected.controlled_load, wire.prepared.controlled_load)

local feedback = wire.led_feedback
local attrs = Indicators.metadata(feedback, feedback.entity_id, selected.device_id, "fixture-led-control")
T.truthy("the real Bridge LED snapshot passes the locator proof", attrs)
local indicator = Indicators.project(attrs)[1]
T.eq("the real Bridge confirmation preserves color and discrete brightness", {
  indicator.color,
  indicator.brightness,
  indicator.levels,
}, { "0000FF", 60, { 30, 60, 100 } })
T.finish()
